#include "can_v_usr_private.h"	 

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/
void can_v_usr_irq_service (Can_Dev_Id dev_id, Can_Irq can_irq)
{
	switch (can_irq)
	{
		case CAN_IRQ_BUS_OFF:
		{
			can_v_usr_err_add (CAN_V_USR_ERR_BUS_OFF, dev_id) ;
		}
		break ;
		 
		case CAN_IRQ_OVERRUN:
		{
			can_v_usr_err_add (CAN_V_USR_ERR_RX_OVERRUN, dev_id) ;
		}
		break ;

		case CAN_IRQ_ERRATA:
		{
			can_v_usr_err_add (CAN_V_USR_ERR_RX_ERRATA, dev_id) ;
		}
		break ;
	}	
}

